CREATE TRIGGER UNDGSubstanceCFR_Version_Create
	ON UNDGSubstanceCFR
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT CFR_PK, 'CFR'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstanceCFR_Version_Update
	ON UNDGSubstanceCFR
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON CFR_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
